import json,pathlib
out=[]
def add(id,zh,en,family,genome,structure,symptoms,transmission,risk,prevention,treatment,mechanism,progress,future,url,date,group='zoonotic'):
 keys=['pathogen','genome','structure','receptor','symptoms','transmission','risk','prevention','treatment','mechanism','progress','future']
 values=[[zh+'。',en+'.'],[{'-ssRNA':'负链单链RNA','+ssRNA':'正链单链RNA','dsDNA':'双链DNA'}[genome],{'-ssRNA':'Negative-sense single-stranded RNA','+ssRNA':'Positive-sense single-stranded RNA','dsDNA':'Double-stranded DNA'}[genome]],structure,['本条以公共卫生概述为范围，未展开分子受体细节。','Molecular receptor details are outside this public-health overview.'],symptoms,transmission,risk,prevention,treatment,mechanism,progress,['建议（编辑综合）：'+future[0],'Suggested priorities (editorial synthesis): '+future[1]]]
 out.append(dict(id=id,zh=zh,en=en,family=family,genome=genome,group=group,fields=dict(zip(keys,values)),verified='2026-11-20',sources=[dict(title=('CDC' if 'cdc.gov' in url else 'WHO')+' · '+en,url=url,scope='症状、传播、临床风险与防治概述；进展限该来源日期',date=date),dict(title='ICTV · '+family,url='https://ictv.global/report/chapter/'+family.lower()+'/'+family.lower(),scope='科级基因组及结构背景；分组内物种不代表完全相同',date='动态报告 / accessed 2026-11-20')]))
add('rabies','狂犬病病毒','Rabies virus','Rhabdoviridae','-ssRNA',['有包膜，典型弹状颗粒。','Enveloped, typically bullet-shaped particles.'],['发热、伤口异常感觉，继而恐水或麻痹。','Fever, unusual wound sensations, then hydrophobia or paralysis.'],['感染哺乳动物的唾液经咬伤、抓伤或黏膜暴露传播。','Infected mammal saliva through bites, scratches or mucosal exposure.'],['出现临床症状后几乎总是致命。','Almost invariably fatal once clinical symptoms appear.'],['犬免疫；暴露后立即清洗伤口并就医评估疫苗及被动免疫。','Dog vaccination; immediate wound washing and medical assessment for post-exposure vaccination and passive immunization.'],['发病后以支持和姑息治疗为主；暴露后预防不应等到发病。','Supportive and palliative care after disease onset; do not delay post-exposure prevention until symptoms.'],['感染进展至中枢神经系统并引起脑脊髓炎。','Infection reaches the central nervous system and causes encephalomyelitis.'],['有效暴露后预防已建立，资源可及性仍是主要缺口。','Effective post-exposure prevention is established; access remains a major gap.'],['改善暴露后预防可及性、监测与犬免疫覆盖。','Access to post-exposure prevention, surveillance and dog vaccination coverage.'],'https://www.who.int/news-room/fact-sheets/detail/rabies','2026-09-17')
add('ebola','埃博拉病相关病毒组','Ebola disease viruses','Filoviridae','-ssRNA',['有包膜，丝状颗粒。','Enveloped, filamentous particles.'],['发热、明显乏力、呕吐腹泻；部分病例出血。','Fever, profound weakness, vomiting and diarrhoea; some patients bleed.'],['直接接触患者或死者的感染性体液及污染物。','Direct contact with infectious body fluids or contaminated materials.'],['休克、多器官衰竭与死亡。','Shock, multiorgan failure and death.'],['感染防控、接触者追踪；适用病毒对应的疫苗。','Infection control, contact tracing and virus-specific vaccination where available.'],['强化支持治疗；获批特异疗法针对埃博拉病毒，不能外推到所有相关病毒。','Intensive supportive care; approved specific therapies for Ebola virus do not generalize to every related virus.'],['全身感染与炎症反应可造成器官功能损害。','Systemic infection and inflammation can impair organ function.'],['WHO资料列出埃博拉病毒的已批准疫苗／治疗，其他埃博拉病产品仍在研发。','WHO lists approved Ebola virus vaccines/therapies; products for other Ebola diseases remain in development.'],['扩大及时诊治和幸存者照护，评估候选防治产品。','Earlier care, survivor follow-up and evaluation of candidate medical products.'],'https://www.who.int/news-room/fact-sheets/detail/ebola-disease','2025-04-24')
add('marburg','马尔堡病相关病毒','Marburg disease viruses','Filoviridae','-ssRNA',['有包膜，丝状颗粒。','Enveloped, filamentous particles.'],['突发高热、头痛、腹泻；可出现出血。','Abrupt fever, headache and diarrhoea; bleeding can occur.'],['动物暴露及接触感染者体液或污染物。','Animal exposure and contact with infectious body fluids or materials.'],['休克、多器官衰竭和死亡。','Shock, multiorgan failure and death.'],['避免高风险动物暴露，落实医疗感染防控。','Reduce hazardous animal exposures and implement healthcare infection control.'],['早期强化支持治疗；所引WHO资料未列已批准特异治疗。','Early intensive supportive care; the cited WHO source lists no approved specific therapy.'],['系统性感染与炎症导致组织及器官损伤。','Systemic infection and inflammation cause tissue and organ injury.'],['WHO资料列出候选疫苗、抗体与抗病毒药的临床评估需求。','WHO identifies clinical evaluation of candidate vaccines, antibodies and antivirals.'],['提高早诊能力、优化支持治疗与临床试验可及性。','Early diagnosis, supportive care and clinical-trial access.'],'https://www.who.int/news-room/fact-sheets/detail/marburg-virus-disease','2025-01-20')
add('nipah','尼帕病毒','Nipah virus','Paramyxoviridae','-ssRNA',['有包膜，多形性颗粒。','Enveloped, pleomorphic particles.'],['发热、头痛、意识改变或呼吸困难。','Fever, headache, altered consciousness or breathing difficulty.'],['感染动物、受污染食物及人与人密切接触。','Infected animals, contaminated food and close person-to-person contact.'],['脑炎、严重肺部疾病及长期神经系统后遗症。','Encephalitis, severe lung disease and neurological sequelae.'],['食品防污染、避免病畜接触及落实医疗防护。','Food protection, avoiding sick animals and healthcare precautions.'],['及时支持治疗；所引WHO资料未列已批准疫苗或特异药物。','Prompt supportive care; the cited WHO source lists no approved vaccine or specific drug.'],['感染可累及脑、肺及其他器官。','Infection can affect the brain, lungs and other organs.'],['WHO将其列为研发优先疾病，候选产品在不同开发阶段。','A WHO R&D priority; candidate products are at different development stages.'],['验证候选产品、强化早诊与幸存者神经康复。','Evaluate medical products, earlier diagnosis and neurological rehabilitation.'],'https://www.who.int/news-room/fact-sheets/detail/nipah-virus','2026-01-29')
add('mpox','猴痘病毒','Monkeypox virus (mpox)','Poxviridae','dsDNA',['复杂、有膜的痘病毒颗粒。','Complex, membrane-containing poxvirus particles.'],['疼痛性皮疹、黏膜病变、发热和淋巴结肿大。','Painful rash, mucosal lesions, fever and enlarged lymph nodes.'],['密切皮肤／黏膜接触、污染物及母婴传播。','Close skin or mucosal contact, contaminated materials and vertical transmission.'],['免疫低下者可出现广泛病变；妊娠可有不良结局。','Disseminated disease in immunocompromised people; adverse pregnancy outcomes.'],['按风险与当地建议接种，避免接触病损与污染物。','Risk-based vaccination under local guidance; avoid lesions and contaminated materials.'],['支持治疗及疼痛、继发感染管理；特异药物须由专科按当地指南评估。','Supportive care, pain relief and secondary-infection management; specialists assess specific medicines under local guidance.'],['皮肤黏膜感染和炎症形成病损。','Skin and mucosal infection and inflammation produce lesions.'],['已有疫苗；药物适应证与疗效证据需要持续核对。','Vaccines exist; drug indications and efficacy evidence require ongoing review.'],['加强临床疗效证据、疫苗可及性及特殊人群照护。','Clinical efficacy evidence, vaccine access and care for vulnerable groups.'],'https://www.who.int/news-room/fact-sheets/detail/mpox','2024-08-26')
add('yellow-fever','黄热病毒','Yellow fever virus','Flaviviridae','+ssRNA',['有包膜，近球形颗粒。','Enveloped, approximately spherical particles.'],['发热、肌痛、恶心；重症出现黄疸和出血。','Fever, muscle pain and nausea; severe cases develop jaundice and bleeding.'],['受感染蚊叮咬传播。','Bites of infected mosquitoes.'],['肝肾衰竭、休克和死亡。','Liver and kidney failure, shock and death.'],['适宜人群接种黄热疫苗并防蚊。','Yellow fever vaccination for eligible people and mosquito-bite prevention.'],['支持治疗；研究性抗病毒疗法不等同于常规治疗。','Supportive care; investigational antivirals are not routine treatment.'],['感染可损害肝脏及其他器官。','Infection can damage the liver and other organs.'],['疫苗提供持久保护；2025年WHO资料将候选抗病毒疗法限定在研究环境。','Vaccines provide durable protection; WHO 2025 guidance limits candidate antivirals to research settings.'],['填补免疫空白，改进早期识别和治疗证据。','Close immunization gaps and improve early recognition and treatment evidence.'],'https://www.who.int/news-room/fact-sheets/detail/yellow-fever','2025-10-20','vector')
add('west-nile','西尼罗病毒','West Nile virus','Flaviviridae','+ssRNA',['有包膜，近球形颗粒。','Enveloped, approximately spherical particles.'],['多数无症状；可有发热、头痛，少数出现脑炎。','Often asymptomatic; fever and headache occur, with occasional encephalitis.'],['主要经蚊叮咬；少见经输血或移植传播。','Mainly mosquito bites; rare transmission through transfusion or transplantation.'],['神经侵袭性疾病、瘫痪及死亡。','Neuroinvasive disease, paralysis and death.'],['防蚊、媒介监测及血液安全。','Mosquito protection, vector surveillance and blood safety.'],['重症支持治疗；所引资料未列特异性治疗。','Supportive care for severe illness; cited information lists no specific therapy.'],['少数感染累及中枢神经系统。','A minority of infections affect the central nervous system.'],['人用疫苗与特异治疗仍是所引资料识别的缺口；旧版来源不代表2026研发全景。','Human vaccines and specific therapy remain gaps in the cited source; this older source is not a 2026 R&D survey.'],['人用预防工具、神经康复和早期预警。','Human prevention tools, neurological rehabilitation and early warning.'],'https://www.who.int/news-room/fact-sheets/detail/west-nile-virus','2017-10-03','vector')
add('hantavirus','人类致病汉坦病毒组','Human-pathogenic hantaviruses','Hantaviridae','-ssRNA',['有包膜，基因组分节段。','Enveloped particles with a segmented genome.'],['发热、肌痛；可继发呼吸困难或肾功能异常。','Fever and myalgia; respiratory distress or renal dysfunction may follow.'],['主要与啮齿动物排泄物暴露有关；安第斯病毒可人际传播。','Mainly exposure to rodent excreta; Andes virus can spread between people.'],['肺综合征或肾综合征出血热，可致休克和死亡。','Pulmonary syndrome or haemorrhagic fever with renal syndrome, with possible shock and death.'],['减少鼠类接触与居住环境鼠害，遵循当地防护建议。','Reduce rodent contact and infestation; follow local prevention advice.'],['以支持治疗为主；重症可能需呼吸或肾脏支持。','Supportive care; severe cases may need respiratory or renal support.'],['感染相关的血管屏障异常可影响肺或肾脏功能。','Infection-associated vascular barrier dysfunction can affect lung or kidney function.'],['临床重点仍是早诊和器官支持；具体防治政策因病毒和地区而异。','Early diagnosis and organ support remain central; prevention policies vary by virus and region.'],['更早识别重症，验证治疗方案与长期康复结局。','Earlier recognition of severe disease, treatment evaluation and long-term recovery.'],'https://www.cdc.gov/hantavirus/about/index.html','2024-05-13')
p=pathlib.Path(__file__).parent
(p/'profiles-c.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
all_profiles=[]
for name in ['a','b','c']:all_profiles+=json.loads((p/('profiles-'+name+'.json')).read_text())
(p.parent/'dist/profiles.json').write_text(json.dumps(all_profiles,ensure_ascii=False,separators=(',',':')))
print('profiles',len(all_profiles))
